import React, { useState, useEffect } from "react";
import { ethers } from "ethers";

// Ganti dengan alamat kontrak kamu di testnet/mainnet
const CONTRACT_ADDRESS = "0xYourContractAddressHere";

// ABI minimal yang dipakai (sesuai smart contract)
const CONTRACT_ABI = [
  "function mintTicket(address attendee, string calldata metadataURI, uint256 priceCap, uint256 expirationTimestamp) external returns (uint256)",
  "function validateTicket(uint256 tokenId) external",
  "function transferTicket(address to, uint256 tokenId, uint256 price) external",
  "function getTicketInfo(uint256 tokenId) external view returns (tuple(string metadataURI,uint256 resalePriceCap,uint256 expiration,bool used))",
  "function setValidator(address validator, bool status) external",
  "event TicketMinted(uint256 indexed tokenId, address indexed attendee, string metadataURI)",
  "event TicketValidated(uint256 indexed tokenId, address indexed validator)",
  "event TicketTransferred(uint256 indexed tokenId, address from, address to, uint256 price)"
];

function App() {
  const [provider, setProvider] = useState(null);
  const [signer, setSigner] = useState(null);
  const [contract, setContract] = useState(null);
  const [account, setAccount] = useState(null);

  const [mintData, setMintData] = useState({
    attendee: "",
    metadataURI: "",
    priceCap: "",
    expiration: ""
  });

  const [tokenId, setTokenId] = useState("");
  const [info, setInfo] = useState(null);

  // Connect wallet
  async function connectWallet() {
    if (window.ethereum) {
      const prov = new ethers.providers.Web3Provider(window.ethereum);
      await prov.send("eth_requestAccounts", []);
      const sign = prov.getSigner();
      const addr = await sign.getAddress();
      setProvider(prov);
      setSigner(sign);
      setAccount(addr);
      setContract(new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, sign));
    } else {
      alert("Please install Metamask!");
    }
  }

  // Mint ticket
  async function mintTicket() {
    if (!contract) return alert("Connect wallet first");
    try {
      const tx = await contract.mintTicket(
        mintData.attendee,
        mintData.metadataURI,
        ethers.utils.parseEther(mintData.priceCap),
        Math.floor(new Date(mintData.expiration).getTime() / 1000)
      );
      await tx.wait();
      alert("Ticket minted successfully!");
    } catch (err) {
      alert("Error minting ticket: " + err.message);
    }
  }

  // Get ticket info
  async function getTicket() {
    if (!contract || !tokenId) return alert("Connect wallet and input tokenId");
    try {
      const ticket = await contract.getTicketInfo(tokenId);
      setInfo(ticket);
    } catch (err) {
      alert("Error fetching ticket info: " + err.message);
    }
  }

  // Validate ticket
  async function validate() {
    if (!contract || !tokenId) return alert("Connect wallet and input tokenId");
    try {
      const tx = await contract.validateTicket(tokenId);
      await tx.wait();
      alert("Ticket validated!");
    } catch (err) {
      alert("Error validating ticket: " + err.message);
    }
  }

  // Transfer ticket
  async function transfer(to, price) {
    if (!contract || !tokenId) return alert("Connect wallet and input tokenId");
    try {
      const tx = await contract.transferTicket(to, tokenId, ethers.utils.parseEther(price));
      await tx.wait();
      alert("Ticket transferred!");
    } catch (err) {
      alert("Error transferring ticket: " + err.message);
    }
  }

  return (
    <div style={{ maxWidth: 600, margin: "auto", padding: 20 }}>
      <h1>EventChain Ticketing DApp</h1>
      {!account ? (
        <button onClick={connectWallet}>Connect Wallet</button>
      ) : (
        <p>Connected account: {account}</p>
      )}

      <hr />

      <h3>Mint Ticket</h3>
      <input
        type="text"
        placeholder="Attendee address"
        value={mintData.attendee}
        onChange={(e) => setMintData({ ...mintData, attendee: e.target.value })}
      />
      <input
        type="text"
        placeholder="Metadata URI"
        value={mintData.metadataURI}
        onChange={(e) => setMintData({ ...mintData, metadataURI: e.target.value })}
      />
      <input
        type="text"
        placeholder="Price Cap (ETH)"
        value={mintData.priceCap}
        onChange={(e) => setMintData({ ...mintData, priceCap: e.target.value })}
      />
      <input
        type="datetime-local"
        value={mintData.expiration}
        onChange={(e) => setMintData({ ...mintData, expiration: e.target.value })}
      />
      <button onClick={mintTicket}>Mint Ticket</button>

      <hr />

      <h3>Get Ticket Info</h3>
      <input
        type="number"
        placeholder="Token ID"
        value={tokenId}
        onChange={(e) => setTokenId(e.target.value)}
      />
      <button onClick={getTicket}>Get Info</button>

      {info && (
        <div>
          <p>Metadata URI: {info.metadataURI}</p>
          <p>Price Cap: {ethers.utils.formatEther(info.resalePriceCap)} ETH</p>
          <p>Expiration: {new Date(info.expiration * 1000).toLocaleString()}</p>
          <p>Used: {info.used ? "Yes" : "No"}</p>
        </div>
      )}

      <hr />

      <h3>Validate Ticket</h3>
      <button onClick={validate}>Validate Ticket</button>

      <hr />

      <h3>Transfer Ticket</h3>
      <input
        type="text"
        placeholder="Recipient Address"
        onChange={(e) => (window.recipient = e.target.value)}
      />
      <input
        type="text"
        placeholder="Price (ETH)"
        onChange={(e) => (window.transferPrice = e.target.value)}
      />
      <button onClick={() => transfer(window.recipient, window.transferPrice)}>Transfer</button>
    </div>
  );
}

export default App;
